// AsNewSource returns the union data inside the Source as a NewSource
func (t Source) AsNewSource() (NewSource, error) {
	var body NewSource
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromNewSource overwrites any union data inside the Source as the provided NewSource
func (t *Source) FromNewSource(v NewSource) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"new"}`))
	t.union = b
	return err
}

// MergeNewSource performs a merge with any union data inside the Source, using the provided NewSource
func (t *Source) MergeNewSource(v NewSource) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"new"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

